import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"Debugging (entry page)","description":"","frontmatter":{},"headers":[],"relativePath":"dev/debugging.md","filePath":"dev/debugging.md"}'),r={name:"dev/debugging.md"};function n(i,e,d,l,c,h){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="debugging-entry-page" tabindex="-1">Debugging (entry page) <a class="header-anchor" href="#debugging-entry-page" aria-label="Permalink to &quot;Debugging (entry page)&quot;">​</a></h1><p>The short orientation. The full compendium - serial extraction, the klog ring, crash dumps and register snapshots, the silent-failure methodology, and the fault-injection tools - now lives in <a href="./debug-handbook.html">debug-handbook.md</a>; the inventory of test programs and hidden flags lives in <a href="./debug-interfaces.html">debug-interfaces.md</a>. This page keeps the daily-driver essentials and points onward.</p><h2 id="read-the-boot-log-first" tabindex="-1">Read the boot log first <a class="header-anchor" href="#read-the-boot-log-first" aria-label="Permalink to &quot;Read the boot log first&quot;">​</a></h2><p>Every subsystem prints one <code>.... OK</code> line at bring-up. The last line that did NOT print is your failing subsystem. Capture it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -serial file:boot.log -display none</span></span></code></pre></div><h2 id="in-guest-tools" tabindex="-1">In-guest tools <a class="header-anchor" href="#in-guest-tools" aria-label="Permalink to &quot;In-guest tools&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; dmesg            (kernel ring replay; dmesg N for more lines)</span></span>
<span class="line"><span>ush&gt; logcat -f        (live follow of the kernel log)</span></span>
<span class="line"><span>ush&gt; logctl status    (levels, filters, file state)</span></span>
<span class="line"><span>ush&gt; health           (CPU/mem/tasks/IO + the three alarm bits)</span></span>
<span class="line"><span>ush&gt; exc              (exception self-test - proves the trap path)</span></span>
<span class="line"><span>ush&gt; crashlog         (past crash records)</span></span>
<span class="line"><span>ush&gt; dumpinfo         (core dump status)</span></span>
<span class="line"><span>ush&gt; crashtest dump   (capture a dump WITHOUT panicking - wiring check)</span></span></code></pre></div><p>Line format everywhere: <code>[SSS.mmm] LEVEL module: message</code>.</p><h2 id="the-panic-path" tabindex="-1">The panic path <a class="header-anchor" href="#the-panic-path" aria-label="Permalink to &quot;The panic path&quot;">​</a></h2><p>A kernel panic dumps the exception frame (registers + fault address + traceback) to serial and writes the crashlog ring; <code>/var/crash/core.dump</code> carries the OCDUMP01 image when a filesystem is mounted. <code>crashtest</code> triggers a deliberate one - use it to validate that your capture wiring works <em>before</em> you need it. What each register means per exception class: <a href="./debug-handbook.html">debug-handbook.md</a> section 3.</p><h2 id="nothing-is-wrong-but-nothing-works" tabindex="-1">Nothing is wrong but nothing works? <a class="header-anchor" href="#nothing-is-wrong-but-nothing-works" aria-label="Permalink to &quot;Nothing is wrong but nothing works?&quot;">​</a></h2><p>Work the silent-failure ladder: health alarms -&gt; the log <em>ring</em> (not the live console) -&gt; the kcap capture trap (captured ops swallow live output - check the routing style) -&gt; return-value conventions (an L1SVC call &quot;succeeds&quot; when it routes; failure text lives inside <code>out</code>) -&gt; recognize the honest-skip strings. Full methodology: <a href="./debug-handbook.html">debug-handbook.md</a> section 4.</p><h2 id="host-side-debugging-of-the-kernel" tabindex="-1">Host-side debugging of the kernel <a class="header-anchor" href="#host-side-debugging-of-the-kernel" aria-label="Permalink to &quot;Host-side debugging of the kernel&quot;">​</a></h2><ul><li>Debug symbols: the pipeline links with <code>-g</code>, then strips the final ELF; <code>build/opencube_base.elf</code> (pre-<code>strip</code>, produced during <code>make kernel</code>) is your symbol carrier.</li><li>In QEMU: <code>-d int,cpu_reset -D qemu.log</code> logs interrupts and resets; <code>-s -S</code> plus gdb (<code>target remote localhost:1234</code>) gives the classic remote-debug loop.</li><li>The reproducible build means a crash reproduced twice is <em>the same bytes</em> - no heisen-builds across attempts (<code>make reproducible-check</code>).</li></ul><h2 id="host-unit-tests" tabindex="-1">Host unit tests <a class="header-anchor" href="#host-unit-tests" aria-label="Permalink to &quot;Host unit tests&quot;">​</a></h2><p><code>make test</code> compiles and runs the harnesses under <code>tests/host_*.c</code> against the real kernel sources (crypto vectors, tar, gzip, string, FAT structures, MB2 parsing with ASAN on the host compiler). A regression here is much faster to iterate on than a boot loop. Inventory: <a href="./host-tests.html">host-tests.md</a>.</p><h2 id="known-sharp-edges-from-the-audit-trail" tabindex="-1">Known-sharp edges (from the audit trail) <a class="header-anchor" href="#known-sharp-edges-from-the-audit-trail" aria-label="Permalink to &quot;Known-sharp edges (from the audit trail)&quot;">​</a></h2><ul><li>xHCI DMA above 4 GiB is refused at probe and per-transfer - check your QEMU memory size if an xHCI device vanishes.</li><li>ATA-DMA alignment depends on the heap&#39;s 32-byte block header; if you touch <code>mem_heap.c</code>, run <code>fstest</code> + a FAT32 mount test.</li><li>The multiboot2 parser validates tag sizes; a &quot;hand-built&quot; mbi in tests must respect the per-tag minimums or the parse stops early.</li><li>QEMU drops serial RX bytes right after an HMP screendump - functional rounds never take screenshots (<a href="./qemu-testing.html">qemu-testing.md</a> section 4).</li><li>A captured L1SVC op suppresses BOTH the framebuffer and the serial tee while it runs - ops that park or own a live session must route direct (the kcap trap, <a href="./debug-handbook.html">debug-handbook.md</a> 4.3).</li><li>A <code>#DF</code> panic is deliberately minimal (one static serial line, no record/dump/flush) - do not expect a dump from a double fault.</li></ul><h2 id="symptom-first-move-quick-reference" tabindex="-1">Symptom -&gt; first move (quick reference) <a class="header-anchor" href="#symptom-first-move-quick-reference" aria-label="Permalink to &quot;Symptom -&gt; first move (quick reference)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>First move</th><th>Why</th></tr></thead><tbody><tr><td>Boot stops mid-ladder</td><td>read the serial boot log; last missing <code>OK</code> line = failing subsystem</td><td>every subsystem prints one <code>.... OK</code> at bring-up</td></tr><tr><td>Machine hangs, console dead</td><td><code>/HANGAT</code>-style? check watchdog status + <code>crashlog</code> after reset</td><td>the 15 s soft dog + the 6300ESB relay produce evidence, not silence</td></tr><tr><td>Kernel panic</td><td>copy the serial banner + register dump; <code>crashlog</code>/<code>dumpinfo</code> after reboot</td><td>the OCDUMP01 image + 32-slot ring survive</td></tr><tr><td>User program misbehaves</td><td>run it under <code>run &lt;name&gt;</code>; <code>ps</code> before/after; check <code>exc</code></td><td>ring-3 faults are kills, not panics - the kernel continues</td></tr><tr><td>Command &quot;does nothing&quot;</td><td>check the routing style + the return convention; look for honest-skip strings</td><td>an L1SVC call &quot;succeeds&quot; when it routes; failure text is inside <code>out</code></td></tr><tr><td>Output vanished mid-op</td><td>the kcap capture trap</td><td>captures suppress live channels</td></tr><tr><td>Storage corruption suspicion</td><td><code>fsck &lt;dev&gt;</code>, <code>disk_rw_test &lt;dev&gt;</code>, cache stats in <code>lsblk</code></td><td>the write-back cache only releases dirty slots on successful write-back</td></tr><tr><td>Network stall</td><td><code>netstat</code>, <code>tcpstats</code> (RTO/cwnd/SACK state), <code>net_rx_bad_checksum</code></td><td>the conn table tells you which layer stalled</td></tr><tr><td>Suspected entropy/crypto issue</td><td><code>cryptotest</code>, <code>dhtest</code></td><td>NIST-vector gates on the exact primitives TLS/SSH use</td></tr></tbody></table><h2 id="filing-a-debuggable-report" tabindex="-1">Filing a debuggable report <a class="header-anchor" href="#filing-a-debuggable-report" aria-label="Permalink to &quot;Filing a debuggable report&quot;">​</a></h2><p>Before reporting a kernel-side problem, collect this checklist - every item is a mechanism the tree already gives you:</p><ol><li><strong>The build identity</strong>: <code>uname -a</code> output (version string + the numeric build id that the OTA comparison uses) - the reproducible build means those two numbers pin the exact bytes.</li><li><strong>The full serial log</strong> (<code>-serial file:boot.log</code>), not a screenshot of the tail - the boot ladder&#39;s last missing <code>OK</code> line names the failing subsystem.</li><li><strong>The klog ring tail</strong>: <code>dmesg 200</code> (and <code>logctl status</code> so filters/levels are known); note the footer <code>-- &lt;shown&gt; lines (ring &lt;count&gt;/1024, dropped &lt;n&gt;) --</code>.</li><li><strong>Crash evidence, if any</strong>: the panic banner + register dump from serial, then after reboot <code>crashlog</code> (and <code>crashlog flush</code>) plus <code>dumpinfo</code>; the OCDUMP01 image from <code>/var/crash/core.dump</code> when a filesystem was mounted.</li><li><strong>The health snapshot</strong> (<code>health</code>) - the alarms line and the five metric sections rule the usual suspects in or out.</li><li><strong>Reproduction steps</strong> on a clean <code>make run-bios</code> boot, and whether <code>make reproducible-check</code> passes on your tree (a crash reproduced twice is the same bytes).</li><li>For QEMU: the exact command line (machine type matters - TCO exists on q35 only) and the QEMU version.</li></ol><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Page</th></tr></thead><tbody><tr><td>Serial/klog/crash evidence, register reading, fault injection</td><td><a href="./debug-handbook.html">debug-handbook.md</a></td></tr><tr><td>The ~93 test programs, diag depth, hidden flags</td><td><a href="./debug-interfaces.html">debug-interfaces.md</a></td></tr><tr><td>Internal call paths (execve, L1SVC, RX, block IO, crash, OTA)</td><td><a href="./call-chains.html">call-chains.md</a></td></tr><tr><td>Kernel structures and who touches them</td><td><a href="./data-structures.html">data-structures.md</a></td></tr><tr><td>QEMU errata, sendkey, OVMF</td><td><a href="./qemu-testing.html">qemu-testing.md</a></td></tr><tr><td>Subsystem deep dives (klog, crash, health, watchdog, crypto, OTA, OCIRE embed)</td><td><a href="./../internals/">../internals/index.md</a></td></tr></tbody></table>`,25)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
